from abc import ABC, abstractmethod
from pathlib import Path
from typing import Dict, Optional


class AbstractSidecarStore(ABC):
    """Abstract interface for sidecar persistence."""

    @abstractmethod
    def save(self, image_path: str, result: Dict) -> str:
        """Persist an extraction result dict and return the sidecar path."""
        ...

    @abstractmethod
    def load(self, image_path: str) -> Optional[Dict]:
        """Read and parse a sidecar JSON for the given image, or None."""
        ...

    @abstractmethod
    def exists(self, image_path: str) -> bool:
        """Return True if a sidecar exists for the given image."""
        ...

    @classmethod
    @abstractmethod
    def sidecar_path(cls, image_path: str) -> Path:
        """Return the expected sidecar JSON path for a given image."""
        ...

import json
import logging
import os
import tempfile
from pathlib import Path
from typing import Dict, Optional

from .store import AbstractSidecarStore
from .database import FeaturesDatabase

logger = logging.getLogger(__name__)


class SidecarWriter(AbstractSidecarStore):
    """Write extraction results as a sidecar JSON file next to the source image.

    Output goes to ``<image_dir>/.open-photo-agent/data/<image>.json`` using
    an atomic tempfile+replace pattern.
    """

    @classmethod
    def sidecar_path(cls, image_path: str) -> Path:
        """Return the expected sidecar JSON path for a given image."""
        img = Path(image_path)
        return img.parent / ".open-photo-agent" / "data" / f"{img.name}.json"

    @classmethod
    def load(cls, image_path: str) -> Optional[Dict]:
        """Read and parse a sidecar JSON for the given image.

        Args:
            image_path: Absolute path to the source image file.

        Returns:
            The parsed dict if the sidecar exists and is valid JSON, or None.
        """
        sp = cls.sidecar_path(image_path)
        if not sp.is_file():
            return None
        try:
            return json.loads(sp.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError):
            return None

    def exists(self, image_path: str) -> bool:
        """Return True if a sidecar exists for the given image."""
        return self.sidecar_path(image_path).is_file()

    def save(self, image_path: str, result: Dict) -> str:
        """Persist an extraction result dict to the sidecar directory.

        Args:
            image_path: Absolute path to the source image file.
            result: A dict containing extraction result fields (success,
                response, parsed, model, durations, error, etc.).

        Returns:
            The absolute path to the written sidecar JSON file.
        """
        img = Path(image_path)
        sidecar_dir = img.parent / ".open-photo-agent" / "data"

        try:
            sidecar_dir.mkdir(parents=True, exist_ok=True)
        except OSError as e:
            logger.error(f"Failed to create sidecar directory {sidecar_dir}: {e}")
            raise

        sidecar_path = self.sidecar_path(image_path)
        payload = {
            "image_path": str(img),
            "success": result.get("success", False),
            "model": result.get("model"),
            "prompt": result.get("prompt"),
            "response": result.get("response"),
            "parsed": result.get("parsed"),
            "total_duration_ms": result.get("total_duration_ms"),
            "eval_count": result.get("eval_count"),
            "done": result.get("done"),
            "error": result.get("error"),
            "error_code": result.get("error_code"),
            "embedding_error": result.get("embedding_error"),
        }
        payload = {k: v for k, v in payload.items() if v is not None}

        try:
            fd, tmp_path = tempfile.mkstemp(
                suffix=".json", prefix=f".{img.name}.", dir=str(sidecar_dir)
            )
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(payload, f, indent=2, ensure_ascii=False)
            os.replace(tmp_path, sidecar_path)
        except OSError as e:
            logger.error(f"Failed to write sidecar {sidecar_path}: {e}")
            raise

        logger.info(f"Saved sidecar: {sidecar_path}")
        return str(sidecar_path)


class DatabaseSidecarStore(AbstractSidecarStore):
    """Write extraction results to the per-folder SQLite ``features.db``.

    Replaces individual JSON sidecars with upserts into the ``raw_features``
    table, enabling fast querying and concurrent reads.
    """

    def __init__(self):
        self._dbs: Dict[str, FeaturesDatabase] = {}

    def _get_db(self, image_path: str) -> FeaturesDatabase:
        folder = str(Path(image_path).parent)
        if folder not in self._dbs:
            db_path = FeaturesDatabase.default_db_path(folder)
            self._dbs[folder] = FeaturesDatabase(db_path)
        return self._dbs[folder]

    @classmethod
    def sidecar_path(cls, image_path: str) -> Path:
        """Return the expected database path for a given image."""
        return FeaturesDatabase.default_db_path(Path(image_path).parent)

    def save(self, image_path: str, result: Dict) -> str:
        """Persist an extraction result dict to the folder's features.db.

        Returns:
            The absolute path to the database file.
        """
        db = self._get_db(image_path)
        db.save_extraction(image_path, result)
        return str(db.db_path)

    def load(self, image_path: str) -> Optional[Dict]:
        """Read an extraction result for the given image from the DB."""
        db = self._get_db(image_path)
        return db.get_extraction(image_path)

    def exists(self, image_path: str) -> bool:
        """Return True if a DB row exists for the given image."""
        db = self._get_db(image_path)
        return db.is_processed(image_path)

from abc import ABC, abstractmethod
from typing import List, Optional

from src.sidecar import AbstractSidecarStore, get_writer
from .result import ProcessingResult


class ResultSaver(ABC):
    """Abstract sink for processing results."""

    @abstractmethod
    def save(self, result: ProcessingResult) -> None:
        """Persist (or collect) one ProcessingResult."""
        ...


class SidecarResultSaver(ResultSaver):
    """Write each result as a sidecar JSON file next to the source image."""

    def __init__(self, store: Optional[AbstractSidecarStore] = None):
        """Initialise with the given sidecar store (defaults to singleton)."""
        self._writer = store or get_writer()

    def save(self, result: ProcessingResult) -> None:
        data = result.as_dict()
        if result.image_path:
            self._writer.save(result.image_path, data)


class CollectingSidecarSaver(SidecarResultSaver):
    """Like SidecarResultSaver but also accumulates results in a list."""

    def __init__(self, store: Optional[AbstractSidecarStore] = None):
        super().__init__(store=store)
        self.results: List[dict] = []

    def save(self, result: ProcessingResult) -> None:
        super().save(result)
        self.results.append(result.as_dict())


class InMemoryCollector(ResultSaver):
    """Accumulate ProcessingResult objects in memory (no sidecar write)."""

    def __init__(self):
        self.results: List[ProcessingResult] = []

    def save(self, result: ProcessingResult) -> None:
        self.results.append(result)


class NoOpResultSaver(ResultSaver):
    """Discards all results (useful for testing or dry-runs)."""

    def save(self, result: ProcessingResult) -> None:
        pass

import sqlite3

import dash
import dash_bootstrap_components as dbc
from dash import Input, Output, State, dash_table, html, callback

from .common import _db_session


def register_sql_explorer_callback(app):
    @callback(
        Output("sql-explorer-modal", "is_open"),
        Input("btn-sql-explorer", "n_clicks"),
        Input("btn-close-sql-explorer", "n_clicks"),
        State("sql-explorer-modal", "is_open"),
        prevent_initial_call=True,
    )
    def toggle_sql_explorer_modal(n_open, n_close, is_open):
        ctx = dash.callback_context
        if not ctx.triggered:
            return dash.no_update

        trigger_id = ctx.triggered[0]["prop_id"].split(".")[0]
        if trigger_id == "btn-sql-explorer":
            return True
        elif trigger_id == "btn-close-sql-explorer":
            return False
        return is_open

    @callback(
        Output("sql-results", "children"),
        Input("btn-run-sql", "n_clicks"),
        State("input-folder", "value"),
        State("sql-input", "value"),
        prevent_initial_call=True,
    )
    def run_sql(n_clicks, folder, sql_text):
        if n_clicks is None:
            return dash.no_update

        if not folder:
            return dbc.Alert(
                "Enter a folder path above before running queries.",
                color="warning",
            )

        with _db_session(folder) as db:
            if db is None:
                return dbc.Alert(
                    "No features.db found for this folder. Scan the folder first.",
                    color="warning",
                )
            try:
                columns, rows = db.execute_query(sql_text)
            except (sqlite3.Error, FileNotFoundError, OSError) as e:
                return dbc.Alert(str(e), color="danger")

        if not columns:
            return html.Div("Query returned no columns.", className="text-muted")

        if not rows:
            return html.Div("Query returned an empty result set.", className="text-muted")

        return dash_table.DataTable(
            columns=[{"name": c, "id": c} for c in columns],
            data=[dict(zip(columns, row)) for row in rows],
            style_table={"overflowX": "auto"},
            sort_action="native",
            filter_action="native",
            page_action="native",
            page_size=20,
        )

import dash
import dash_bootstrap_components as dbc
from dash import Input, Output, State, html

from src.components import build_photo_cards

from .common import _db_session


def register_search_callback(app):
    @app.callback(
        Output("search-results", "children"),
        Output("search-status", "children"),
        Output("photo-list-store", "data", allow_duplicate=True),
        Input("btn-search", "n_clicks"),
        State("search-input", "value"),
        State("input-folder", "value"),
        prevent_initial_call=True,
    )
    def run_search(btn_search, query, folder):
        if btn_search is None:
            return dash.no_update, dash.no_update, dash.no_update

        if not folder:
            return (
                dash.no_update,
                dbc.Alert("Enter a folder path above before searching.", color="warning"),
                dash.no_update,
            )

        with _db_session(folder) as db:
            if db is None:
                return (
                    dash.no_update,
                    dbc.Alert(
                        "No features.db found for this folder. Process the folder first.",
                        color="warning",
                    ),
                    dash.no_update,
                )

            if not query:
                return (
                    dash.no_update,
                    dbc.Alert("Enter a search query.", color="warning"),
                    dash.no_update,
                )
            results = db.search_features(query)
            if not results:
                return (
                    html.Div("No results found.", className="text-muted"),
                    dash.no_update,
                    dash.no_update,
                )
            return (
                build_photo_cards(results, folder=folder, source="search"),
                dbc.Alert(f"{len(results)} result(s) found.", color="success", dismissable=True),
                {"paths": [r.get("image_path", "") for r in results], "index": None},
            )

import json
import logging

import dash
import dash_bootstrap_components as dbc
from dash import Input, Output, State, callback_context, html

from src.components import build_photo_cards, build_selected_tags_bar, build_tag_cloud

from .common import _db_session

logger = logging.getLogger(__name__)


def register_tag_cloud_load_callback(app):
    """Load tag frequency data into a store when the user clicks Load Tag Cloud."""
    @app.callback(
        Output("tag-cloud-data-store", "data"),
        Input("btn-load-tag-cloud", "n_clicks"),
        State("input-folder", "value"),
        prevent_initial_call=True,
    )
    def load_tag_cloud(n_clicks, folder):
        if n_clicks is None:
            return dash.no_update

        if not folder:
            return {"folder": "", "tags": []}

        with _db_session(folder) as db:
            if db is None:
                return {"folder": folder, "tags": []}
            try:
                tags_with_counts = db.list_tag_frequencies()
            except (sqlite3.Error, OSError) as e:
                logger.warning("Failed to load tag frequencies: %s", e)
                return {"folder": folder, "tags": []}

        # Serialize tag tuples to lists for JSON
        return {"folder": folder, "tags": tags_with_counts}


def register_tag_cloud_render_callback(app):
    """Render the tag cloud and selected-tags bar from stores.

    Shows the full tag cloud when no filters are active.
    When tags are selected, the cloud is restricted to tags that
    co-occur with the active selection in at least one photo.
    """
    @app.callback(
        Output("tag-cloud-container", "children"),
        Output("selected-tags-bar", "children"),
        Input("tag-cloud-data-store", "data"),
        Input("selected-tags-store", "data"),
        prevent_initial_call=True,
    )
    def render_tag_cloud(tag_cloud_data, selected_tags):
        if not tag_cloud_data:
            return html.Div(), html.Div()

        folder = tag_cloud_data.get("folder", "")
        if not folder:
            return html.Div(), html.Div()

        selected_tags = list(selected_tags or [])

        if not selected_tags:
            # No active filters — show everything that was loaded.
            tags_with_counts = tag_cloud_data.get("tags", [])
        else:
            # Active filters — query DB for co-occurring tags.
            with _db_session(folder) as db:
                if db is None:
                    return html.Div(), html.Div()
                try:
                    tags_with_counts = db.list_tag_frequencies_restricted(
                        selected_tags, limit=100
                    )
                except (sqlite3.Error, OSError) as e:
                    logger.warning("Failed to load restricted tag frequencies: %s", e)
                    tags_with_counts = []

        if not tags_with_counts:
            msg = (
                "No other tags co-occur with the current selection."
                if selected_tags else "No tags found."
            )
            return html.Div(msg, className="text-muted"), build_selected_tags_bar(selected_tags)

        return build_tag_cloud(
            tags_with_counts, selected_tags=selected_tags
        ), build_selected_tags_bar(selected_tags)


def register_tag_toggle_callback(app):
    """Handle tag click, pill removal, and clear-all for the tag chain."""
    @app.callback(
        Output("selected-tags-store", "data"),
        Output("tag-cloud-results", "children"),
        Output("photo-list-store", "data", allow_duplicate=True),
        Input({"type": "tag-cloud-btn", "index": dash.ALL}, "n_clicks"),
        Input({"type": "tag-clear-btn", "index": dash.ALL}, "n_clicks"),
        Input("btn-tag-clear-all", "n_clicks"),
        State({"type": "tag-cloud-btn", "index": dash.ALL}, "id"),
        State({"type": "tag-clear-btn", "index": dash.ALL}, "id"),
        State("selected-tags-store", "data"),
        State("input-folder", "value"),
        prevent_initial_call=True,
    )
    def tag_toggled(_tag_cloud_clicks, _clear_tag_clicks, _clear_all_clicks,
                    _tag_cloud_ids, _clear_tag_ids, current_tags, folder):
        ctx = callback_context
        if not ctx.triggered:
            return dash.no_update, dash.no_update, dash.no_update

        triggered_id = ctx.triggered[0].get("prop_id", "")
        if triggered_id == ".":
            return dash.no_update, dash.no_update, dash.no_update

        # Handle Clear All
        if "btn-tag-clear-all" in triggered_id:
            return [], html.Div(), dash.no_update

        # Identify clicked tag and whether it's a removal
        clicked_tag = None
        remove = False
        for t in ctx.triggered:
            prop_id = t.get("prop_id", "")
            if not t.get("value"):
                continue
            if "tag-cloud-btn" in prop_id:
                try:
                    id_part = prop_id.rsplit(".", 1)[0]
                    btn_id = json.loads(id_part)
                    clicked_tag = btn_id.get("index")
                    remove = False
                except (json.JSONDecodeError, ValueError):
                    continue
            elif "tag-clear-btn" in prop_id:
                try:
                    id_part = prop_id.rsplit(".", 1)[0]
                    btn_id = json.loads(id_part)
                    clicked_tag = btn_id.get("index")
                    remove = True
                except (json.JSONDecodeError, ValueError):
                    continue

        if not clicked_tag:
            return dash.no_update, dash.no_update, dash.no_update

        current_tags = list(current_tags or [])
        current_lower = {t.lower() for t in current_tags}
        is_active = clicked_tag.lower() in current_lower

        if remove:
            new_tags = [t for t in current_tags if t.lower() != clicked_tag.lower()]
        elif is_active:
            new_tags = [t for t in current_tags if t.lower() != clicked_tag.lower()]
        else:
            new_tags = current_tags + [clicked_tag]

        if not new_tags:
            return [], html.Div(), dash.no_update

        if not folder:
            return new_tags, dbc.Alert("Enter a folder path above.", color="warning"), dash.no_update

        with _db_session(folder) as db:
            if db is None:
                return new_tags, dbc.Alert(
                    "No features.db found for this folder.",
                    color="warning",
                ), dash.no_update
            try:
                results = db.get_features_by_tags(new_tags)
            except (sqlite3.Error, OSError) as e:
                logger.warning("Failed to get features by tags: %s", e)
                return new_tags, dbc.Alert(f"Error loading photos: {e}", color="danger"), dash.no_update

        children = html.Div(
            [
                dbc.Alert(f"Photos tagged with: {', '.join(new_tags)}", color="info", dismissable=False),
                build_photo_cards(results, folder=folder, source="tag") if results else html.Div("No photos match all selected tags.", className="text-muted"),
            ]
        )
        list_data = {"paths": [r.get("image_path", "") for r in results], "index": None} if results else dash.no_update
        return new_tags, children, list_data

import json
import logging

import dash
from dash import Input, Output, State, callback_context, html

from src.components import build_detail_modal_content, build_fullscreen_viewer

from .common import _db_session, _open_fullscreen_content, _open_modal
from .similarity import _get_db

logger = logging.getLogger(__name__)


def register_detail_modal_callback(app):
    @app.callback(
        Output("detail-modal", "is_open"),
        Output("detail-modal-body", "children"),
        Output("photo-list-store", "data", allow_duplicate=True),
        Input({"type": "thumbnail", "source": dash.ALL, "index": dash.ALL}, "n_clicks"),
        Input("btn-prev-photo", "n_clicks"),
        Input("btn-next-photo", "n_clicks"),
        Input("btn-close-detail", "n_clicks"),
        State({"type": "thumbnail", "source": dash.ALL, "index": dash.ALL}, "id"),
        State("photo-list-store", "data"),
        State("input-folder", "value"),
        prevent_initial_call=True,
    )
    def handle_modal(_thumbnail_clicks, _prev_clicks, _next_clicks, _close_clicks,
                     _thumbnail_ids, store_data, folder):
        ctx = callback_context
        if not ctx.triggered:
            return dash.no_update, dash.no_update, dash.no_update

        prop_id = ""
        value = None
        for t in ctx.triggered:
            pid = t.get("prop_id", "")
            val = t.get("value")
            if pid and pid != ".":
                prop_id = pid
                value = val
                break
        else:
            return dash.no_update, dash.no_update, dash.no_update

        # Close modal
        if "btn-close-detail" in prop_id:
            return False, dash.no_update, dash.no_update

        paths = store_data.get("paths", []) if isinstance(store_data, dict) else []
        current_index = store_data.get("index") if isinstance(store_data, dict) else None

        # Previous photo
        if "btn-prev-photo" in prop_id:
            if current_index is not None and paths:
                new_index = (current_index - 1) % len(paths)
                image_path = paths[new_index]
                return _open_modal(image_path, folder, new_index, paths)
            return dash.no_update, dash.no_update, dash.no_update

        # Next photo
        if "btn-next-photo" in prop_id:
            if current_index is not None and paths:
                new_index = (current_index + 1) % len(paths)
                image_path = paths[new_index]
                return _open_modal(image_path, folder, new_index, paths)
            return dash.no_update, dash.no_update, dash.no_update

        # Thumbnail click
        if "thumbnail" in prop_id:
            if not value:
                return dash.no_update, dash.no_update, dash.no_update
            try:
                id_part = prop_id.rsplit(".", 1)[0]
                btn_id = json.loads(id_part)
                image_path = btn_id.get("index")
            except (json.JSONDecodeError, ValueError):
                return dash.no_update, dash.no_update, dash.no_update

            if not image_path or not folder:
                return dash.no_update, dash.no_update, dash.no_update

            if image_path in paths:
                new_index = paths.index(image_path)
            else:
                # Fallback: path not in current list, treat as single-image view
                paths = [image_path]
                new_index = 0

            return _open_modal(image_path, folder, new_index, paths)

        return dash.no_update, dash.no_update, dash.no_update


def register_fullscreen_open_callback(app):
    """Open the fullscreen viewer from the detail modal's Fullscreen button."""
    @app.callback(
        Output("fullscreen-modal", "is_open"),
        Output("fullscreen-modal-body", "children"),
        Input("btn-open-fullscreen", "n_clicks"),
        State("photo-list-store", "data"),
        State("detail-modal", "is_open"),
        State("input-folder", "value"),
        prevent_initial_call=True,
    )
    def open_fullscreen(n_clicks, store_data, detail_is_open, folder):
        if not n_clicks or not folder or not detail_is_open:
            return dash.no_update, dash.no_update

        paths = store_data.get("paths", []) if isinstance(store_data, dict) else []
        current_index = store_data.get("index") if isinstance(store_data, dict) else None

        if current_index is None or current_index >= len(paths):
            return dash.no_update, dash.no_update

        image_path = paths[current_index]
        content, _ = _open_fullscreen_content(image_path, folder, current_index, paths)
        return True, content


def register_fullscreen_nav_callback(app):
    """Handle prev/next navigation inside the fullscreen viewer."""
    @app.callback(
        Output("fullscreen-modal-body", "children", allow_duplicate=True),
        Output("photo-list-store", "data", allow_duplicate=True),
        Input("btn-prev-fullscreen", "n_clicks"),
        Input("btn-next-fullscreen", "n_clicks"),
        State("photo-list-store", "data"),
        State("input-folder", "value"),
        prevent_initial_call=True,
    )
    def navigate_fullscreen(_prev_clicks, _next_clicks, store_data, folder):
        ctx = callback_context
        if not ctx.triggered:
            return dash.no_update, dash.no_update

        prop_id = ""
        for t in ctx.triggered:
            pid = t.get("prop_id", "")
            if pid and pid != ".":
                prop_id = pid
                break
        else:
            return dash.no_update, dash.no_update

        paths = store_data.get("paths", []) if isinstance(store_data, dict) else []
        current_index = store_data.get("index") if isinstance(store_data, dict) else None

        if current_index is None or not paths:
            return dash.no_update, dash.no_update

        if "btn-prev-fullscreen" in prop_id:
            new_index = (current_index - 1) % len(paths)
        elif "btn-next-fullscreen" in prop_id:
            new_index = (current_index + 1) % len(paths)
        else:
            return dash.no_update, dash.no_update

        image_path = paths[new_index]
        content, store = _open_fullscreen_content(image_path, folder, new_index, paths)
        return content, store


def register_fullscreen_close_callback(app):
    """Close the fullscreen viewer and update the detail modal to reflect any
    navigation that happened inside fullscreen."""
    @app.callback(
        Output("fullscreen-modal", "is_open", allow_duplicate=True),
        Output("detail-modal-body", "children", allow_duplicate=True),
        Input("btn-close-fullscreen", "n_clicks"),
        State("photo-list-store", "data"),
        State("input-folder", "value"),
        prevent_initial_call=True,
    )
    def close_fullscreen(n_clicks, store_data, folder):
        if not n_clicks:
            return dash.no_update, dash.no_update

        paths = store_data.get("paths", []) if isinstance(store_data, dict) else []
        current_index = store_data.get("index") if isinstance(store_data, dict) else None

        updated_body = dash.no_update
        if current_index is not None and current_index < len(paths) and folder:
            image_path = paths[current_index]
            metadata = None
            embedding = None
            embedding_error = None
            with _db_session(folder) as db:
                if db is not None:
                    try:
                        metadata = db.get_feature_summary(image_path)
                        # Try to get embedding vector
                        try:
                            from src.config import AppConfig
                            config = AppConfig.from_env()
                            embedding = db.get_embedding(image_path, config.embedding_model)
                        except RuntimeError as e:
                            # sqlite-vss not available - don't truncate this important error
                            embedding_error = f"Vector search not available: {str(e)}"
                            logger.debug("sqlite-vss not available for %s: %s", image_path, e)
                        except Exception as e:
                            # Other error (e.g., embedding not found)
                            embedding_error = f"Embedding not found: {str(e)[:100]}"
                            logger.debug("No embedding found for %s: %s", image_path, e)
                    except Exception:
                        logger.warning("Failed to load metadata for %s", image_path, exc_info=True)
            updated_body = build_detail_modal_content(image_path, folder, metadata, embedding, embedding_error)

        return False, updated_body


